/// Publication Verification - one node's verdicts on received notices.
#[derive(Copy, Clone, PartialEq)]
pub struct PNV<'a> {
    pub _tab: ::flatbuffers::Table<'a>,
}

impl<'a> ::flatbuffers::Follow<'a> for PNV<'a> {
    type Inner = PNV<'a>;

    #[inline]
    unsafe fn follow(buf: &'a [u8], loc: usize) -> Self::Inner {
        Self { _tab: unsafe { ::flatbuffers::Table::new(buf, loc) } }
    }
}

impl<'a> PNV<'a> {
    pub const VT_VERIFIER_PEER_ID: ::flatbuffers::VOffsetT = 4;
    pub const VT_GENERATED_AT_MS: ::flatbuffers::VOffsetT = 6;
    pub const VT_ENTRIES: ::flatbuffers::VOffsetT = 8;
    pub const VT_ETAG: ::flatbuffers::VOffsetT = 10;

    #[inline]
    pub unsafe fn init_from_table(table: ::flatbuffers::Table<'a>) -> Self {
        PNV { _tab: table }
    }

    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: ::flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut ::flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args PNVArgs<'args>
    ) -> ::flatbuffers::WIPOffset<PNV<'bldr>> {
        let mut builder = PNVBuilder::new(_fbb);
        builder.add_GENERATED_AT_MS(args.GENERATED_AT_MS);
        if let Some(x) = args.ETAG { builder.add_ETAG(x); }
        if let Some(x) = args.ENTRIES { builder.add_ENTRIES(x); }
        if let Some(x) = args.VERIFIER_PEER_ID { builder.add_VERIFIER_PEER_ID(x); }
        builder.finish()
    }

    pub fn unpack(&self) -> PNVT {
        let VERIFIER_PEER_ID = self.VERIFIER_PEER_ID().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let GENERATED_AT_MS = self.GENERATED_AT_MS();
        let ENTRIES = self.ENTRIES().map(|x| {
            x.iter().map(|t| t.unpack()).collect()
        });
        let ETAG = self.ETAG().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        PNVT {
            VERIFIER_PEER_ID,
            GENERATED_AT_MS,
            ENTRIES,
            ETAG,
        }
    }

    /// Identifier of the node that verified.
    #[inline]
    pub fn VERIFIER_PEER_ID(&self) -> Option<&'a str> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<&str>>(PNV::VT_VERIFIER_PEER_ID, None)}
    }

    /// Unix milliseconds when this set was generated.
    #[inline]
    pub fn GENERATED_AT_MS(&self) -> i64 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<i64>(PNV::VT_GENERATED_AT_MS, Some(0)).unwrap()}
    }

    #[inline]
    pub fn ENTRIES(&self) -> Option<::flatbuffers::Vector<'a, ::flatbuffers::ForwardsUOffset<PNVEntry<'a>>>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'a, ::flatbuffers::ForwardsUOffset<PNVEntry>>>>(PNV::VT_ENTRIES, None)}
    }

    /// Entity tag of this set, for conditional requests.
    #[inline]
    pub fn ETAG(&self) -> Option<&'a str> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<&str>>(PNV::VT_ETAG, None)}
    }
}

impl ::flatbuffers::Verifiable for PNV<'_> {
    #[inline]
    fn run_verifier(
        v: &mut ::flatbuffers::Verifier, pos: usize
    ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
        v.visit_table(pos)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("VERIFIER_PEER_ID", Self::VT_VERIFIER_PEER_ID, false)?
            .visit_field::<i64>("GENERATED_AT_MS", Self::VT_GENERATED_AT_MS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, ::flatbuffers::ForwardsUOffset<PNVEntry>>>>("ENTRIES", Self::VT_ENTRIES, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("ETAG", Self::VT_ETAG, false)?
            .finish();
        Ok(())
    }
}

