/// Assumes, without verification, that a buffer of bytes contains a size prefixed PNV and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `PNV`.
#[inline]
pub unsafe fn size_prefixed_root_as_pnv_unchecked(buf: &[u8]) -> PNV<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<PNV>(buf) }
}

pub const PNV_IDENTIFIER: &str = "$PNV";

#[inline]
pub fn pnv_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, PNV_IDENTIFIER, false)
}

#[inline]
pub fn pnv_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, PNV_IDENTIFIER, true)
}

#[inline]
pub fn finish_pnv_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<PNV<'a>>
) {
    fbb.finish(root, Some(PNV_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_pnv_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<PNV<'a>>
) {
    fbb.finish_size_prefixed(root, Some(PNV_IDENTIFIER));
}
